  const renamed = renameDeal(paused, '  Café 😀  ');
  assert.deepEqual({ ...renamed.game, name: paused.game.name }, paused.game);
  assert.deepEqual({ ...renamed, game: paused.game }, paused);
  assert.equal(renamed.game.name, '  Café 😀  ');
  assert.equal(renameDeal(renamed, 'x'.repeat(41)), renamed, 'overlong name is ignored');
  assert.equal(renameDeal(renamed, 'line\nbreak'), renamed, 'line feeds are ignored');
  assert.equal(renameDeal(renamed, 'line\rbreak'), renamed, 'carriage returns are ignored');
  let completed = initial;
  for (const pair of EXAMPLE_PAIRS)
    for (const index of pair) completed = activateSession(completed, index);
  assert.equal(completed.celebration, true);
  const renamedCompleted = renameDeal(completed, 'Finished deal');
  assert.equal(renamedCompleted.game.name, 'Finished deal');
