});

test('named snapshots keep state validation for all progress fields', () => {
  const named = {
    ...validSnapshot(2),
    name: 'Saved',
    started: true,
    moves: 0,
    selection: { kind: SelectionKind.one, index: 0 },
  };
  assert.ok(
    decodeSnapshot(JSON.stringify(named)),
