  );
  const invalid = [
    { boardCode: 'bad' },
    { matched: [0], moves: 1, selection: { kind: SelectionKind.one, index: 3 } },
    { selection: { kind: SelectionKind.one, index: 16 } },
    { moves: -1 },
    { elapsedMs: Number.MAX_SAFE_INTEGER + 1 },
    { started: 'true' },
